# Databricks notebook source
# MAGIC %md
# MAGIC # 09 · Metric views
# MAGIC Creates the Unity Catalog metric views over three gold tables: the approval, volume, decline and funnel
# MAGIC measures, defined once as ratios of sums, so the dashboard and Genie compute them the same way. Query them with
# MAGIC `MEASURE()`, for example `SELECT country, MEASURE(final_approval_rate) FROM approval_metrics GROUP BY ALL`.
# MAGIC
# MAGIC Generated by `tools/build_databricks.py` from `databricks/metric_views/*.yml`. Do not edit by hand.

# COMMAND ----------

spark.sql(r"""
CREATE OR REPLACE VIEW workspace.approval_copilot.approval_metrics
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Card approval and approved volume per day, country, card type and first acquirer. Every rate is a ratio of sums over the rows in scope.
source: workspace.approval_copilot.gold_approval_daily
dimensions:
  - name: business_date
    expr: business_date
    comment: Local calendar date of the payment (country time zone)
  - name: month
    expr: date_trunc('MONTH', business_date)
    comment: First day of the local calendar month
  - name: country
    expr: country
    comment: "Country code: 'MX', 'CO' or 'BR'"
  - name: card_type
    expr: card_type
    comment: "'credit' or 'debit'"
  - name: first_acquirer
    expr: acquirer_id
    comment: "First acquirer chosen by routing: 'A', 'B' or 'C'. Results are attributed to it"
  - name: is_cross_border
    expr: is_cross_border
    comment: "Boolean: true when the card was issued abroad, false for domestic payments. Compare approval rates between segments on domestic traffic unless asked; counts and volumes cover both unless the question says domestic or cross-border"
measures:
  - name: payments_sent
    expr: SUM(payments_sent)
    comment: Payments that reached an acquirer
  - name: final_approved
    expr: SUM(final_approved)
    comment: Payments approved on the first attempt or after a retry on a second acquirer
  - name: final_approval_rate
    expr: SUM(final_approved) / SUM(payments_sent)
    comment: Final approval rate, recomputed from counts
  - name: first_attempt_approval_rate
    expr: SUM(first_attempt_approved) / SUM(payments_sent)
    comment: Approval rate of the first attempt, the routing KPI
  - name: approved_usd
    expr: SUM(approved_usd)
    comment: Approved volume in USD
  - name: attempted_usd
    expr: SUM(attempted_usd)
    comment: Volume sent to acquirers in USD
  - name: approved_volume_rate
    expr: SUM(approved_usd) / SUM(attempted_usd)
    comment: Share of the volume sent that was approved
  - name: fees_usd
    expr: SUM(fees_usd)
    comment: Acquirer fees on the approved volume, USD
$$
""")  # noqa: F821
print("created approval_metrics")

# COMMAND ----------

spark.sql(r"""
CREATE OR REPLACE VIEW workspace.approval_copilot.decline_metrics
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Failed authorization attempts per day, country, card type, acquirer and canonical reason, with how the decline-code map classified each code at the time. It holds failed attempts only, so a share of all attempts needs payments_sent from approval_metrics as the denominator.
source: workspace.approval_copilot.gold_decline_reasons_daily
dimensions:
  - name: business_date
    expr: business_date
    comment: Local calendar date of the attempt (country time zone)
  - name: country
    expr: country
    comment: "Country code: 'MX', 'CO' or 'BR'"
  - name: card_type
    expr: card_type
    comment: "'credit' or 'debit'"
  - name: acquirer
    expr: acquirer_id
    comment: "Acquirer that processed the attempt: 'A', 'B' or 'C'"
  - name: attempt
    expr: CASE WHEN attempt_seq = 1 THEN 'first attempt' ELSE 'retry' END
    comment: "'first attempt' for the first authorization, 'retry' for the retry on a second acquirer"
  - name: reason_code
    expr: reason_code
    comment: "Normalized ISO 8583 response code ('05', '14', '1A', '41', '43', '51', '54', '57', '59', '61', '62', '65', '91', '96', 'N7') or the canonical status of a technical failure ('TECHNICAL_ERROR', 'TIMEOUT'). '05' is do not honor, '51' insufficient funds"
  - name: reason
    expr: reason
    comment: "Reason in plain words, capitalized exactly as stored: 'Do not honor', 'Insufficient funds', 'Additional authentication required (3DS)', 'Expired card', 'Transaction not permitted to cardholder', 'Invalid card number', 'Exceeds amount limit', 'Suspected fraud', 'CVV2 mismatch', 'Issuer or switch unavailable', 'Technical Error', 'Restricted card', 'Exceeds frequency limit', 'System malfunction', 'Timeout', 'Stolen card', 'Lost card'. Filtering on reason_code is safer"
  - name: decline_type
    expr: decline_type
    comment: "'soft', 'hard' or 'technical', as the map classified the code at that time"
  - name: retryable
    expr: retryable
    comment: "Boolean: true when the map allowed a retry on another acquirer, false when it did not"
  - name: mapping_version
    expr: mapping_version
    comment: "Version of the decline-code map in force: 'v2.2', 'v2.3' or 'v2.3.1'"
measures:
  - name: failed_attempts
    expr: SUM(attempts)
    comment: Authorization attempts the issuer or the acquirer did not approve. Dividing it by failed attempts gives a share of the failures. A share of all first attempts divides it by MEASURE(payments_sent) from approval_metrics over the same filters, without the reason
$$
""")  # noqa: F821
print("created decline_metrics")

# COMMAND ----------

spark.sql(r"""
CREATE OR REPLACE VIEW workspace.approval_copilot.funnel_metrics
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Payment funnel per day, country and card type, from checkout intent to approval, including payments the risk engine blocked and 3DS challenges the customer abandoned. Covers domestic and cross-border payments. Every rate is a ratio of sums over the rows in scope.
source: workspace.approval_copilot.gold_funnel_daily
dimensions:
  - name: business_date
    expr: business_date
    comment: Local calendar date of the payment intent (country time zone)
  - name: month
    expr: date_trunc('MONTH', business_date)
    comment: First day of the local calendar month
  - name: country
    expr: country
    comment: "Country code: 'MX', 'CO' or 'BR'"
  - name: card_type
    expr: card_type
    comment: "'credit' or 'debit'. Leave it out to get a country's rate over both card types"
measures:
  - name: payment_intents
    expr: SUM(payment_intents)
    comment: Payments created at checkout
  - name: blocked_by_risk
    expr: SUM(blocked_by_risk)
    comment: Intents blocked by the risk engine, including review timeouts
  - name: abandoned_3ds
    expr: SUM(abandoned_3ds)
    comment: Intents abandoned by the customer in the 3DS challenge
  - name: sent_to_acquirer
    expr: SUM(sent_to_acquirer)
    comment: Intents that reached an acquirer
  - name: approved
    expr: SUM(approved)
    comment: Intents finally approved
  - name: conversion_rate
    expr: SUM(approved) / SUM(payment_intents)
    comment: Share of payment intents finally approved
  - name: risk_block_rate
    expr: SUM(blocked_by_risk) / SUM(payment_intents)
    comment: Share of payment intents the risk engine blocked
  - name: abandoned_3ds_rate
    expr: SUM(abandoned_3ds) / SUM(payment_intents)
    comment: Share of payment intents abandoned in the 3DS challenge
$$
""")  # noqa: F821
print("created funnel_metrics")
